669		if err := s2.AdvanceCampaign(spec.ID, upBase.Add(7*time.Minute)); !errors.Is(err, ErrTimeRegression) {
670			t.Fatalf("regression after reopen: %v", err)
671		}
672		// 重复结果判断延续：回滚成功只接受一次，重放不增加历史。
673		res := OperationResult{
674			CampaignID: spec.ID, DeviceID: "d1", OperationID: rbBefore.ID,
675			At: upBase.Add(86 * time.Minute), Success: true,
676			Seq: 2, Version: "v1", Config: json.RawMessage(`{"ok":1}`),
677		}
678		if err := s2.SubmitResult(res); err != nil {
679			t.Fatalf("rollback after reopen: %v", err)
680		}
681		n := len(mustGetCampaign(s2, spec.ID).Results)
682		res.At = upBase.Add(87 * time.Minute)
683		if err := s2.SubmitResult(res); err != nil {
684			t.Fatalf("rollback replay: %v", err)
685		}
686		if len(mustGetCampaign(s2, spec.ID).Results) != n {
687			t.Fatal("rollback replay added history after reopen")
688		}
689		if sh, _ := s2.Get("d1"); sh.Version != "v1" {
690			t.Fatalf("shadow version after reopen rollback: %s", sh.Version)
691		}
692	}
