737			Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":1}`),
738		}); err != nil {
739			t.Fatalf("retry after recovery: %v", err)
740		}
741		if sh, _ := s.Get("d1"); sh.Version != "v1" || sh.LastSeq != 2 {
742			t.Fatalf("shadow after retry: %+v", sh)
743		}
744	}
745	
746	// 旧存储中的活动（无任何回滚字段）可直接打开，回滚缺省关闭并保持旧行为。
747	func TestOldCampaignStorageRollbackDefaultsOff(t *testing.T) {
748		dir := t.TempDir()
749		old := `{
750	 "format":1,
751	 "devices":{"d1":{"version":"v1","online":true,"revision":0,"desired":{},"reported":{},"lastSeq":1,"lastReportTime":"2026-10-02T11:59:00Z"}},
752	 "versions":{"v2":{"target":"v2","allowedFrom":["v1"]}},
753	 "campaigns":{"c1":{"id":"c1","operator":"alice","target":"v2","createdAt":"2026-10-02T12:00:00Z","batchSize":1,"windowStart":"2026-10-02T12:00:00Z","windowEnd":"2026-10-02T13:00:00Z","deadline":"2026-10-02T14:00:00Z","lastTime":"2026-10-02T12:00:00Z","status":"running","ended":false,"devices":[{"deviceId":"d1","batch":0,"status":"pending","phase":"download","download":{"id":"c1:d1:download"},"install":{"id":"c1:d1:install"}}]}}
