	if dl.ID != operationID(spec.ID, "d1", StageDownload) {
		t.Fatalf("unexpected new id: %q", dl.ID)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	s2, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
